package com.bankquantityorder;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(BankQuantityOrderConfig.GROUP)
public interface BankQuantityOrderConfig extends Config
{
	String GROUP = "bankquantityorder";
	String ORDER_KEY = "order";

	@ConfigSection(
		name = "Layout",
		description = "How the bank's bottom row is arranged",
		position = 0
	)
	String layoutSection = "layout";

	@ConfigSection(
		name = "Button visibility",
		description = "Buttons shown in the bank's bottom row",
		position = 10
	)
	String visibilitySection = "visibility";

	@ConfigItem(
		keyName = "dragToReorder",
		name = "Drag to reorder",
		description = "Drag the buttons in the bank's bottom row to change their order.",
		section = layoutSection,
		position = 1
	)
	default boolean dragToReorder()
	{
		return false;
	}

	@ConfigItem(
		keyName = ORDER_KEY,
		name = "",
		description = "",
		hidden = true
	)
	default String order()
	{
		return RowButton.serialize(RowButton.DEFAULT_ORDER);
	}

	@ConfigItem(keyName = "hiddenSpace", name = "Leftover space", description = "What the row does with the space left by hidden buttons.",
		section = layoutSection, position = 2)
	default HiddenSpace hiddenSpace()
	{
		return HiddenSpace.LEAVE_GAPS;
	}

	@ConfigItem(keyName = "uniformWidths", name = "Uniform button widths", description = "Make every button the same width as the others, including search.",
		section = layoutSection, position = 3)
	default boolean uniformWidths()
	{
		return false;
	}

	@ConfigItem(keyName = "dividers", name = "Dividers", description = "Where divider lines go between buttons.",
		section = layoutSection, position = 4)
	default Dividers dividers()
	{
		return Dividers.BETWEEN_SECTIONS;
	}

	@ConfigItem(keyName = "showRearrange", name = "Rearrange mode", description = "Show the Swap/Insert button.",
		section = visibilitySection, position = 11)
	default boolean showRearrange()
	{
		return true;
	}

	@ConfigItem(keyName = "showWithdrawAs", name = "Withdraw as note", description = "Show the Item/Note button.",
		section = visibilitySection, position = 12)
	default boolean showWithdrawAs()
	{
		return true;
	}

	@ConfigItem(keyName = "showQuantity1", name = "Quantity 1", description = "Show the 1 button.",
		section = visibilitySection, position = 13)
	default boolean showQuantity1()
	{
		return true;
	}

	@ConfigItem(keyName = "showQuantity5", name = "Quantity 5", description = "Show the 5 button.",
		section = visibilitySection, position = 14)
	default boolean showQuantity5()
	{
		return true;
	}

	@ConfigItem(keyName = "showQuantity10", name = "Quantity 10", description = "Show the 10 button.",
		section = visibilitySection, position = 15)
	default boolean showQuantity10()
	{
		return true;
	}

	@ConfigItem(keyName = "showQuantityX", name = "Quantity X", description = "Show the X button.",
		section = visibilitySection, position = 16)
	default boolean showQuantityX()
	{
		return true;
	}

	@ConfigItem(keyName = "showQuantityAll", name = "Quantity All", description = "Show the All button.",
		section = visibilitySection, position = 17)
	default boolean showQuantityAll()
	{
		return true;
	}

	@ConfigItem(keyName = "showPlaceholders", name = "Placeholders", description = "Show the placeholders button.",
		section = visibilitySection, position = 18)
	default boolean showPlaceholders()
	{
		return true;
	}

	@ConfigItem(keyName = "showSearch", name = "Search", description = "Show the search button.",
		section = visibilitySection, position = 19)
	default boolean showSearch()
	{
		return true;
	}

	@ConfigItem(keyName = "showEmptyContainers", name = "Empty containers", description = "Show the empty containers button.",
		section = visibilitySection, position = 20)
	default boolean showEmptyContainers()
	{
		return true;
	}

	@ConfigItem(keyName = "showDepositInventory", name = "Deposit inventory", description = "Show the deposit inventory button.",
		section = visibilitySection, position = 21)
	default boolean showDepositInventory()
	{
		return true;
	}

	@ConfigItem(keyName = "showDepositWorn", name = "Deposit worn items", description = "Show the deposit worn items button.",
		section = visibilitySection, position = 22)
	default boolean showDepositWorn()
	{
		return true;
	}
}

package com.bankquantityorder;

import com.google.inject.Provides;
import java.util.Collections;
import java.util.EnumSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetDrag;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetConfig;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * Customizes the buttons in the bank's bottom row: their order (dragged in place), which ones
 * show, how the row fills the space hidden buttons leave, button widths and divider lines.
 * <p>
 * The game's own widgets are moved (not redrawn), so their click handlers,
 * right-click options, hover effects and selected-state highlight are untouched
 * and travel with them. The selected quantity (a varbit) is never written.
 */
@PluginDescriptor(
	name = "Customizable Bank UI",
	description = "Reorder, hide, resize and divide the buttons in the bank's bottom row",
	tags = {"bank", "quantity", "withdraw", "buttons", "reorder", "hide", "layout"}
)
public class BankQuantityOrderPlugin extends Plugin
{
	private static final int DRAG_FLAGS = WidgetConfig.DRAG | WidgetConfig.DRAG_ON;
	// Same thresholds Bank Tags uses for its draggable tabs, so a normal click never starts a drag
	private static final int DRAG_DEAD_ZONE = 5;
	private static final int DRAG_DEAD_TIME = 5;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private BankQuantityOrderConfig config;

	private boolean active;

	private BottomRowLayout layout;

	// Buttons whose drag flags we turned on, so turning dragging off only clears what we set
	private final Set<RowButton> dragEnabled = EnumSet.noneOf(RowButton.class);

	// Widgets this plugin hid, by identity, so showing them again never unhides something the game hid
	private final Set<Widget> hiddenByUs = Collections.newSetFromMap(new IdentityHashMap<>());

	@Provides
	BankQuantityOrderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankQuantityOrderConfig.class);
	}

	@Override
	protected void startUp()
	{
		active = true;
		layout = new BottomRowLayout(client);
		// Handles enabling the plugin while the bank is already open
		clientThread.invokeLater(this::apply);
	}

	@Override
	protected void shutDown()
	{
		active = false;
		// Handles disabling the plugin while the bank is open
		clientThread.invokeLater(() ->
		{
			showAll();
			setDraggable(false);
			layout.restore();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (active && BankQuantityOrderConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invokeLater(this::apply);
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		// Runs after every bank open and bank rebuild (tab switch, search, resize, etc).
		// Event handlers run on the client thread.
		if (active && event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING)
		{
			apply();
		}
	}

	@Subscribe
	public void onWidgetDrag(WidgetDrag event)
	{
		// Fires every frame of any widget drag; only a release over another row button matters
		if (!active || !config.dragToReorder() || client.getMouseCurrentButton() != 0)
		{
			return;
		}

		Widget dragged = client.getDraggedWidget();
		Widget draggedOn = client.getDraggedOnWidget();
		if (dragged == null || draggedOn == null)
		{
			return;
		}

		RowButton moved = RowButton.forButtonId(dragged.getId());
		if (moved == null)
		{
			return;
		}

		// The game would send a drag packet for this release; the buttons are only draggable
		// because of this plugin, so the reorder must stay client-side (as core's prayer reorder does)
		client.setDraggedOnWidget(null);

		RowButton target = RowButton.forButtonId(draggedOn.getId());
		if (target == null || moved == target)
		{
			return;
		}

		List<RowButton> order = RowButton.move(RowButton.parse(config.order()), moved, target);
		// Saving fires ConfigChanged, which re-lays out the row
		configManager.setConfiguration(BankQuantityOrderConfig.GROUP, BankQuantityOrderConfig.ORDER_KEY,
			RowButton.serialize(order));
	}

	private void apply()
	{
		applyVisibility();
		setDraggable(config.dragToReorder());
		layout.apply(RowButton.parse(config.order()), config.hiddenSpace(), config.uniformWidths(), config.dividers());
	}

	private void applyVisibility()
	{
		// Drop widgets from a previous bank session; a reopened bank has new widget objects
		hiddenByUs.removeIf(w -> client.getWidget(w.getId()) != w);

		for (RowButton b : RowButton.values())
		{
			setShown(isShown(b), b.getButtonId(), b.getAttachedId());
		}
	}

	/**
	 * Hides the widgets, or shows again only the ones this plugin hid. Something the game itself
	 * hid is never unhidden.
	 */
	private void setShown(boolean shown, int... widgetIds)
	{
		for (int id : widgetIds)
		{
			Widget w = client.getWidget(id);
			if (w == null)
			{
				continue;
			}
			if (!shown && !w.isSelfHidden())
			{
				w.setHidden(true);
				hiddenByUs.add(w);
			}
			else if (shown && hiddenByUs.remove(w))
			{
				w.setHidden(false);
			}
		}
	}

	private void showAll()
	{
		for (Widget w : hiddenByUs)
		{
			if (client.getWidget(w.getId()) == w)
			{
				w.setHidden(false);
			}
		}
		hiddenByUs.clear();
	}

	private boolean isShown(RowButton b)
	{
		switch (b)
		{
			case REARRANGE:
				return config.showRearrange();
			case WITHDRAW_AS:
				return config.showWithdrawAs();
			case ONE:
				return config.showQuantity1();
			case FIVE:
				return config.showQuantity5();
			case TEN:
				return config.showQuantity10();
			case X:
				return config.showQuantityX();
			case ALL:
				return config.showQuantityAll();
			case SEARCH:
				return config.showSearch();
			case PLACEHOLDERS:
				return config.showPlaceholders();
			case EMPTY_CONTAINERS:
				return config.showEmptyContainers();
			case DEPOSIT_INVENTORY:
				return config.showDepositInventory();
			default:
				return config.showDepositWorn();
		}
	}

	private void setDraggable(boolean draggable)
	{
		for (RowButton b : RowButton.values())
		{
			Widget button = client.getWidget(b.getButtonId());
			if (button == null)
			{
				dragEnabled.clear(); // bank closed; reopened widgets start from the game's own flags
				return;
			}

			int mask = button.getClickMask();
			if (draggable && (mask & DRAG_FLAGS) != DRAG_FLAGS)
			{
				button.setClickMask(mask | DRAG_FLAGS);
				button.setDragDeadZone(DRAG_DEAD_ZONE);
				button.setDragDeadTime(DRAG_DEAD_TIME);
				dragEnabled.add(b);
			}
			else if (!draggable && dragEnabled.remove(b))
			{
				button.setClickMask(mask & ~DRAG_FLAGS);
			}
		}
	}
}

package com.bankquantityorder;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID.Bankmain;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetType;

/**
 * Lays out the bank's bottom row: buttons in the chosen order, the space left by hidden buttons
 * handled per {@link HiddenSpace}, and divider lines per {@link Dividers}.
 * <p>
 * Every position and width this class writes on the game's widgets is recorded. Each layout first
 * puts back what it wrote, unless the game has since written its own value (it repositions the
 * deposit buttons itself), so layouts always start from the game's current arrangement and never
 * drift. Must be used on the client thread.
 */
@Slf4j
class BottomRowLayout
{
	private static final int[] NATIVE_DIVIDERS = {Bankmain.BOTTOM_LINE4, Bankmain.BOTTOM_LINE6, Bankmain.DEPOSIT_LINE};

	// Used only if the game's own spacing can't be read: 1px between buttons, a divider 3px after
	// one button and 4px before the next
	private static final int DEFAULT_BUTTON_GAP = 1;
	private static final int DEFAULT_BEFORE_DIVIDER = 3;
	private static final int DEFAULT_AFTER_DIVIDER = 4;

	/**
	 * A button's widgets and its geometry in the game's arrangement, in row coordinates: quantity
	 * widgets live inside the quantity layer, so their row position is the layer's x plus their own.
	 */
	private static final class Button
	{
		RowButton id;
		Widget main;
		Widget attached;
		int baseX;
		int baseW;
		int attachedBaseX;
		boolean visible;
		int newX;
		int newW;
	}

	private final Client client;
	// {value before we wrote, value we wrote}
	private final Map<Widget, int[]> xWrites = new IdentityHashMap<>();
	private final Map<Widget, int[]> widthWrites = new IdentityHashMap<>();
	private final Set<Widget> hiddenDividers = Collections.newSetFromMap(new IdentityHashMap<>());
	// Extra divider lines this class created for "between buttons"; they live on the row widget
	private final List<Widget> createdDividers = new ArrayList<>();

	BottomRowLayout(Client client)
	{
		this.client = client;
	}

	/**
	 * Puts back everything this class changed, as long as the game hasn't overwritten it since.
	 */
	void restore()
	{
		List<Widget> touched = new ArrayList<>();
		putBack(xWrites, true, touched);
		putBack(widthWrites, false, touched);
		for (Widget w : hiddenDividers)
		{
			if (isCurrent(w))
			{
				w.setHidden(false);
			}
		}
		hiddenDividers.clear();
		for (Widget w : createdDividers)
		{
			w.setHidden(true);
		}
		revalidate(touched);
	}

	void apply(List<RowButton> order, HiddenSpace mode, boolean uniformWidths, Dividers dividers)
	{
		Widget row = client.getWidget(Bankmain.BOTTOM);
		Widget layer = client.getWidget(Bankmain.QUANTITY_LAYER);
		if (row == null || layer == null)
		{
			return; // bank not open
		}

		restore();

		Map<RowButton, Button> buttons = collect(layer);
		List<Widget> nativeDividers = new ArrayList<>();
		for (int id : NATIVE_DIVIDERS)
		{
			Widget w = client.getWidget(id);
			if (w != null && isAbsolute(w))
			{
				nativeDividers.add(w);
			}
		}
		if (buttons == null || nativeDividers.size() != NATIVE_DIVIDERS.length || !isAbsolute(layer))
		{
			log.debug("Bank bottom row not in an expected layout; leaving it alone");
			return;
		}

		// The game's own spacing, read from its arrangement around the first divider
		Button left = buttons.get(RowButton.REARRANGE);
		Button beforeDivider = buttons.get(RowButton.WITHDRAW_AS);
		int firstQuantityX = Integer.MAX_VALUE;
		int rowStart = Integer.MAX_VALUE;
		int rowEnd = Integer.MIN_VALUE;
		for (Button b : buttons.values())
		{
			if (b.id.isQuantity())
			{
				firstQuantityX = Math.min(firstQuantityX, b.baseX);
			}
			rowStart = Math.min(rowStart, b.baseX);
			rowEnd = Math.max(rowEnd, b.baseX + b.baseW);
		}
		int dividerX = nativeDividers.get(0).getOriginalX();
		int buttonGap = sane(beforeDivider.baseX - (left.baseX + left.baseW), DEFAULT_BUTTON_GAP);
		int gapBeforeDivider = sane(dividerX - (beforeDivider.baseX + beforeDivider.baseW), DEFAULT_BEFORE_DIVIDER);
		int gapAfterDivider = sane(firstQuantityX - dividerX, DEFAULT_AFTER_DIVIDER);

		// "Leave gaps" lays out every button, so hidden ones keep their space; the other modes lay
		// out only what's showing
		List<Button> placed = new ArrayList<>();
		for (RowButton id : order)
		{
			Button b = buttons.get(id);
			if (mode == HiddenSpace.LEAVE_GAPS || b.visible)
			{
				placed.add(b);
			}
		}

		int uniformW = commonWidth(buttons.values());
		int n = placed.size();
		boolean[] dividerAfter = new boolean[Math.max(n - 1, 0)];
		int span = 0;
		for (int i = 0; i < n; i++)
		{
			Button b = placed.get(i);
			b.newW = uniformWidths ? uniformW : b.baseW;
			span += b.newW;
			if (i < n - 1)
			{
				dividerAfter[i] = dividers == Dividers.BETWEEN_BUTTONS
					|| (dividers == Dividers.BETWEEN_SECTIONS && b.id.getGroup() != placed.get(i + 1).id.getGroup());
				span += dividerAfter[i] ? gapBeforeDivider + gapAfterDivider : buttonGap;
			}
		}

		int extra = rowEnd - rowStart - span;
		if (mode == HiddenSpace.STRETCH && extra > 0 && n > 0)
		{
			int each = extra / n;
			int remainder = extra % n;
			for (Button b : placed)
			{
				b.newW += each + (remainder-- > 0 ? 1 : 0);
			}
			extra = 0;
		}

		// More dividers than the game's three (e.g. "Between buttons") can need more room than the
		// row has; narrow the buttons evenly so the last one never ends up past the row's edge
		if (extra < 0 && n > 0)
		{
			int each = -extra / n;
			int remainder = -extra % n;
			for (Button b : placed)
			{
				b.newW -= each + (remainder-- > 0 ? 1 : 0);
			}
			extra = 0;
		}

		// "Leave gaps" keeps the row full width: whatever space is left over (from dividers removed or
		// narrower buttons) is shared out evenly between the buttons
		int[] extraGap = new int[Math.max(n - 1, 0)];
		if (mode == HiddenSpace.LEAVE_GAPS && extra > 0 && n > 1)
		{
			for (int i = 0; i < n - 1; i++)
			{
				extraGap[i] = extra / (n - 1) + (i < extra % (n - 1) ? 1 : 0);
			}
			extra = 0;
		}

		int x = mode == HiddenSpace.COLLAPSE_RIGHT ? rowStart + Math.max(extra, 0) : rowStart;
		for (int i = 0; i < n; i++)
		{
			Button b = placed.get(i);
			b.newX = x;
			x += b.newW;
			if (i < n - 1)
			{
				x += (dividerAfter[i] ? gapBeforeDivider + gapAfterDivider : buttonGap) + extraGap[i];
			}
		}

		// Dividers go only between two buttons that are showing (with "Leave gaps", hidden buttons
		// still hold space), centred in the space between them
		List<Integer> dividerPositions = new ArrayList<>();
		Button previous = null;
		for (Button b : placed)
		{
			if (!b.visible)
			{
				continue;
			}
			if (previous != null && (dividers == Dividers.BETWEEN_BUTTONS
				|| (dividers == Dividers.BETWEEN_SECTIONS && previous.id.getGroup() != b.id.getGroup())))
			{
				dividerPositions.add((previous.newX + previous.newW + b.newX) / 2);
			}
			previous = b;
		}

		List<Widget> touched = new ArrayList<>();
		// The quantity layer spans the whole row from x 0, so row coordinates work inside it too and
		// its buttons can sit anywhere along the row
		setX(layer, 0);
		setWidth(layer, rowEnd);
		touched.add(layer);
		for (Button b : placed)
		{
			setX(b.main, b.newX);
			setWidth(b.main, b.newW);
			touched.add(b.main);
			if (b.attached != null)
			{
				// Keep the icon or label centred on the button, however wide the button now is
				setX(b.attached, b.newX + (b.attachedBaseX - b.baseX) + (b.newW - b.baseW) / 2);
				touched.add(b.attached);
			}
		}
		placeDividers(row, nativeDividers, dividerPositions, touched);
		revalidate(touched);
	}

	private void placeDividers(Widget row, List<Widget> nativeDividers, List<Integer> positions, List<Widget> touched)
	{
		// A divider from an earlier bank session is gone with that session; hide it anyway before
		// forgetting it, so a line can never be left behind on screen
		createdDividers.removeIf(w ->
		{
			if (isChildOf(w, row))
			{
				return false;
			}
			w.setHidden(true);
			return true;
		});
		Widget template = nativeDividers.get(0);
		for (int i = 0; i < Math.max(positions.size(), nativeDividers.size()); i++)
		{
			Widget divider;
			if (i < nativeDividers.size())
			{
				divider = nativeDividers.get(i);
				if (i >= positions.size())
				{
					if (!divider.isSelfHidden())
					{
						divider.setHidden(true);
						hiddenDividers.add(divider);
					}
					continue;
				}
				setX(divider, positions.get(i));
			}
			else
			{
				int extraIndex = i - nativeDividers.size();
				if (extraIndex >= createdDividers.size())
				{
					createdDividers.add(createDivider(row, template));
				}
				divider = createdDividers.get(extraIndex);
				divider.setHidden(false);
				divider.setOriginalX(positions.get(i));
			}
			touched.add(divider);
		}
		for (int i = Math.max(positions.size() - nativeDividers.size(), 0); i < createdDividers.size(); i++)
		{
			createdDividers.get(i).setHidden(true);
		}
	}

	/**
	 * A new divider line drawn exactly like the game's own.
	 */
	private static Widget createDivider(Widget row, Widget template)
	{
		Widget w = row.createChild(-1, WidgetType.LINE);
		w.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
		w.setYPositionMode(template.getYPositionMode());
		w.setWidthMode(WidgetSizeMode.ABSOLUTE);
		w.setHeightMode(template.getHeightMode());
		w.setOriginalY(template.getOriginalY());
		w.setOriginalWidth(template.getOriginalWidth());
		w.setOriginalHeight(template.getOriginalHeight());
		w.setTextColor(template.getTextColor());
		return w;
	}

	private static boolean isChildOf(Widget w, Widget parent)
	{
		Widget[] children = parent.getDynamicChildren();
		return children != null && Arrays.asList(children).contains(w);
	}

	private Map<RowButton, Button> collect(Widget layer)
	{
		Map<RowButton, Button> buttons = new HashMap<>();
		for (RowButton id : RowButton.values())
		{
			Widget main = client.getWidget(id.getButtonId());
			Widget attached = client.getWidget(id.getAttachedId());
			if (main == null || !isAbsolute(main) || (attached != null && !isAbsolute(attached)))
			{
				return null;
			}
			int offset = id.isQuantity() ? layer.getOriginalX() : 0;
			Button b = new Button();
			b.id = id;
			b.main = main;
			b.attached = attached;
			b.baseX = offset + main.getOriginalX();
			b.baseW = main.getOriginalWidth();
			b.attachedBaseX = attached == null ? 0 : offset + attached.getOriginalX();
			b.visible = !main.isSelfHidden();
			buttons.put(id, b);
		}
		return buttons;
	}

	/**
	 * The width most of the row's buttons share (search is the one wider exception).
	 */
	private static int commonWidth(Iterable<Button> buttons)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		int best = 0;
		int bestCount = 0;
		for (Button b : buttons)
		{
			int count = counts.merge(b.baseW, 1, Integer::sum);
			if (count > bestCount)
			{
				best = b.baseW;
				bestCount = count;
			}
		}
		return best;
	}

	private static int sane(int measured, int fallback)
	{
		return measured >= 0 && measured <= 20 ? measured : fallback;
	}

	private void setX(Widget w, int x)
	{
		if (w.getOriginalX() != x)
		{
			xWrites.computeIfAbsent(w, k -> new int[]{w.getOriginalX(), 0})[1] = x;
			w.setOriginalX(x);
		}
	}

	private void setWidth(Widget w, int width)
	{
		if (w.getOriginalWidth() != width)
		{
			widthWrites.computeIfAbsent(w, k -> new int[]{w.getOriginalWidth(), 0})[1] = width;
			w.setOriginalWidth(width);
		}
	}

	private void putBack(Map<Widget, int[]> writes, boolean isX, List<Widget> touched)
	{
		for (Map.Entry<Widget, int[]> e : writes.entrySet())
		{
			Widget w = e.getKey();
			int[] rec = e.getValue();
			int current = isX ? w.getOriginalX() : w.getOriginalWidth();
			// If the value isn't the one we wrote, the game has repositioned it; its value wins
			if (isCurrent(w) && current == rec[1])
			{
				if (isX)
				{
					w.setOriginalX(rec[0]);
				}
				else
				{
					w.setOriginalWidth(rec[0]);
				}
				touched.add(w);
			}
		}
		writes.clear();
	}

	private boolean isCurrent(Widget w)
	{
		return client.getWidget(w.getId()) == w;
	}

	private static void revalidate(List<Widget> widgets)
	{
		for (Widget w : widgets)
		{
			revalidateTree(w);
		}
	}

	/**
	 * Revalidates a widget and everything inside it. The search button's bevel is nine pieces sized
	 * from the button's width, so they have to be recomputed whenever the button is resized.
	 */
	private static void revalidateTree(Widget w)
	{
		w.revalidate();
		for (Widget[] children : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()})
		{
			if (children != null)
			{
				for (Widget child : children)
				{
					if (child != null)
					{
						revalidateTree(child);
					}
				}
			}
		}
	}

	private static boolean isAbsolute(Widget w)
	{
		return w.getXPositionMode() == WidgetPositionMode.ABSOLUTE_LEFT
			&& w.getWidthMode() == WidgetSizeMode.ABSOLUTE;
	}
}

