		assertEquals(Arrays.asList(
				REARRANGE, WITHDRAW_AS, TEN, SEARCH, FIVE, ONE, X, ALL, PLACEHOLDERS, EMPTY_CONTAINERS, DEPOSIT_INVENTORY, DEPOSIT_WORN),
			RowButton.move(RowButton.DEFAULT_ORDER, SEARCH, FIVE));
	}
